  // ../src/contract.lawspec:201
  // References: KIP-98
  // for all (t :: Text) (txid :: Text) (g :: Text) (offset :: Int64) => created t 1 implies
  // transactionalOffsets t txid g offset = true end for all
  private static final List<String> BROKER_OFFSETS_SENT_IN_TRANSACTION_ARE_INPUTS =
      List.of("(text)", "(text)", "(text)", "(int Int64 0 9223372036854775807)");

  private Double brokerOffsetsSentInTransactionAreCase(List<Value> values) throws Exception
  {
    var symbols = new HashMap<String, Object>();
    var t = LawSpecRuntime.convert("Text", values.get(0), MACHINE_BITS);
    var txid = LawSpecRuntime.convert("Text", values.get(1), MACHINE_BITS);
    var g = LawSpecRuntime.convert("Text", values.get(2), MACHINE_BITS);
    var offset = LawSpecRuntime.convert("Int64", values.get(3), MACHINE_BITS);
    if (!(LawSpecRuntime.truth(LawSpecDefinitionBodies.lawtwinKafkaModelValidTopicName(symbols, t))
        && LawSpecRuntime.truth(LawSpecRuntime.binary("!=", txid, LawSpecRuntime.text("Text", "")))
        && LawSpecRuntime.truth(LawSpecRuntime.binary("!=", g, LawSpecRuntime.text("Text", "")))
        && LawSpecRuntime.truth(
            LawSpecRuntime.binary(
                ">=",
                offset,
                LawSpecRuntime.convert(
                    "Integer", LawSpecRuntime.integer("Integer", "0"), MACHINE_BITS)))))
    {
      return null;
    }
    var withCluster =
        callAdapterConnectCluster(
            symbols,
            () -> LawSpecRuntime.convert("Unit", LawSpecRuntime.absent("Unit"), MACHINE_BITS));
    try
    {
      LawSpecRuntime.installHandlers(
          symbols,
          java.util.Map.<String, Object>of(
              "lawtwin.kafka::ability::Broker",
              new Kafka.BrokerHandler(
                  LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                      .decode(withCluster))));
      brokerOffsetsSentInTransactionAreCheck(
          "lawtwin.kafka::Broker: |offsets "
              + "sent in a transaction are committed "
              + "only with it| [native] search — "
              + "../src/contract.lawspec:201",
          symbols,
          new Value[] {t, txid, g, offset, withCluster});
    }
    finally
    {
      var withClusterReleased = callAdapterDisconnectCluster(symbols, () -> withCluster);
    }
    return 0.0;
  }

