  private void brokerTheStableOffsetNeverPassesTheHighCheck(
      String context, Map<String, Object> symbols, Value[] values)
  {
    var t = values[0];
    var txid = values[1];
    var batch = values[2];
    var withCluster = values[3];
    if (LawSpecRuntime.truth(
        LawSpecDefinitionBodies.created(
            symbols,
            t,
            LawSpecRuntime.convert("Int32", LawSpecRuntime.integer("Int32", "1"), MACHINE_BITS))))
    {
      LawSpecRuntime.check(
          context,
          () -> LawSpecDefinitionBodies.stableBelowHigh(symbols, t, txid, batch),
          () -> LawSpecRuntime.convert("Bool", LawSpecRuntime.bool(true), MACHINE_BITS));
    }
  }

