  private void brokerTheStableOffsetNeverPassesTheHighBoundaryBody(
      LawSpecRuntime.FiniteCase finiteCase)
  {
    var symbols = new HashMap<String, Object>();
    var values = finiteCase.values(symbols);
    var t = LawSpecRuntime.convert("Text", values.get(0), MACHINE_BITS);
    var txid = LawSpecRuntime.convert("Text", values.get(1), MACHINE_BITS);
    var batch =
        SCHEMA.validate(
            new LawSpecSchema.Named(
                "List", new LawSpecSchema.Named("lawtwin.kafka.model::type::Record")),
            values.get(2),
            MACHINE_BITS,
            symbols);
    var withCluster =
        callAdapterConnectCluster(
            symbols,
            () -> LawSpecRuntime.convert("Unit", LawSpecRuntime.absent("Unit"), MACHINE_BITS));
    try
    {
      LawSpecRuntime.installHandlers(
          symbols,
          java.util.Map.<String, Object>of(
              "lawtwin.kafka::ability::Broker",
              new Kafka.BrokerHandler(
                  LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                      .decode(withCluster))));
      brokerTheStableOffsetNeverPassesTheHighCheck(
          "lawtwin.kafka::Broker: |the stable "
              + "offset never passes the high "
              + "watermark| [native] boundary "
              + finiteCase.index()
              + " — ../src/contract.lawspec:260",
          symbols,
          new Value[] {t, txid, batch, withCluster});
    }
    finally
    {
      var withClusterReleased = callAdapterDisconnectCluster(symbols, () -> withCluster);
    }
  }

