  private void producerRecordsSentToOnePartitionAreReadBoundaryBody(
      LawSpecRuntime.FiniteCase finiteCase)
  {
    var symbols = new HashMap<String, Object>();
    var values = finiteCase.values(symbols);
    var t = LawSpecRuntime.convert("Text", values.get(0), MACHINE_BITS);
    var first =
        SCHEMA.validate(
            new LawSpecSchema.Named("lawtwin.kafka.model::type::Record"),
            values.get(1),
            MACHINE_BITS,
            symbols);
    var second =
        SCHEMA.validate(
            new LawSpecSchema.Named("lawtwin.kafka.model::type::Record"),
            values.get(2),
            MACHINE_BITS,
            symbols);
    var withCluster =
        callAdapterConnectCluster(
            symbols,
            () -> LawSpecRuntime.convert("Unit", LawSpecRuntime.absent("Unit"), MACHINE_BITS));
    try
    {
      LawSpecRuntime.installHandlers(
          symbols,
          java.util.Map.<String, Object>of(
              "lawtwin.kafka::ability::Producer",
              new Kafka.ProducerHandler(
                  LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                      .decode(withCluster)),
              "lawtwin.kafka::ability::Broker",
              new Kafka.BrokerHandler(
                  LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                      .decode(withCluster)),
              "lawtwin.kafka::ability::Consumer",
              new Kafka.ConsumerHandler(
                  LawSpecDataCodecs.clusterCodec(SCHEMA, MACHINE_BITS, symbols)
                      .decode(withCluster))));
      producerRecordsSentToOnePartitionAreReadCheck(
          "lawtwin.kafka::Producer: |records "
              + "sent to one partition are read in "
              + "the order sent| [native] boundary "
              + finiteCase.index()
              + " — ../src/contract.lawspec:1142",
          symbols,
          new Value[] {t, first, second, withCluster});
    }
    finally
    {
      var withClusterReleased = callAdapterDisconnectCluster(symbols, () -> withCluster);
    }
  }

